    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Merge overlapping intervals in each list
    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [intervals[0]]
        for start, end in intervals[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return merged

    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    result = []

    for a_start, a_end in a_merged:
        # Start with the full interval from a
        current_ranges = [[a_start, a_end]]

        # Subtract each interval in b
        for b_start, b_end in b_merged:
            new_ranges = []
            for c_start, c_end in current_ranges:
                # If b doesn't overlap with current range, keep it
                if b_end <= c_start or b_start >= c_end:
                    new_ranges.append([c_start, c_end])
                else:
                    # b overlaps with current range
                    # Add the part before b_start (if any)
                    if c_start < b_start:
                        new_ranges.append([c_start, b_start])
                    # Add the part after b_end (if any)
                    if b_end < c_end:
                        new_ranges.append([b_end, c_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Merge adjacent intervals in result
    if not result:
        return []

    result = sorted(result)
    merged_result = [result[0]]
